# The second list of working pictures of the places after the Heart: far backplates, feature sheets, ground plates and more tiles,
# made by the Builder for the second owners of each place (wave 2 of Phase 4), most of them at an owner's request.
# Kinds: tile (repeats both ways, colour and height data, as in spec.py), plate (one whole picture, written at its own size, not repeated).
# A plate with height=True gets a second picture, <name>-h.png: a grey height or relief picture made from the colour picture by a second call.
# Run: python3 assets-src/materials/spec2.py   (writes assets-src/materials/spec2.json, which the generation step, make-materials.mjs and write-recipes.py read)
import json, os

A = 'references/approved/'
R = 'references/drafts/working/real/'
DIRS = {'ribs': '1-ribs', 'breath': '3-breath', 'marsh': '4-marsh', 'spine': '5-spine', 'eye': '6-eye', 'reveal': '7-reveal'}

def ap(place, n):
    d = DIRS[place]
    f = [x for x in sorted(os.listdir(A + d)) if x.startswith(f'{place}-{n}-')][0]
    return A + d + '/' + f

REAL = "The second reference image is a real photograph: it is the standard for how a camera records the real thing, with real grain, real micro detail and no painted, stylised or generated look. "
NOPE = "Photographic, sharp from edge to edge, no depth of field blur, no vignette, no text, no labels, no arrows, no logo, no border, no people."
BACK = ("This is a background plate for a film: only the far distance, to stand behind built scenery. The first reference image is the place as the film sees it: keep the forms of its far distance, its light, its weather and its colours, and leave out everything near. "
        + REAL + "The horizon is exactly level, straight from the left edge to the right edge. Output one wide landscape image, sixteen units wide and nine tall. " + NOPE + " No animals, no birds.")
SHEET = ("The whole subject lies inside the frame on a pure black background, with a margin of black on every side, and nothing touches the edge of the frame. Flat, even, shadowless light from the front, so that no side is brighter than another and no shadow is cast: a reference plate for texture work, not a scene. "
         "The first reference image is where the subject comes from: take its colours, its age and its character from there, and nothing of its composition. " + REAL + NOPE + " No ground, no horizon, no sky.")
FILL = ("The surface fills the whole frame edge to edge, square on, with no background showing. Flat, even, shadowless light from the front, so that no side is brighter than another: a reference plate for texture work, not a scene. "
        "The first reference image is where the subject comes from: take its colours, its age and its character from there, and nothing of its composition or its perspective. " + REAL + NOPE + " No horizon, no sky, no animals.")
GROUND = ("One piece of ground seen straight down from above in an orthographic view, as a survey photograph: it fills the whole frame edge to edge at one uniform scale and it does not repeat. Flat, even, shadowless overcast light, so that no side of anything is brighter than another. "
          "The first reference image is the place this ground belongs to: take its colours, its age and its character from there, and nothing of its composition or its perspective. " + REAL + NOPE + " No horizon, no sky, no animals.")
TILE = ("Flat, even, shadowless overcast light so that no side is brighter than another. The surface fills the whole frame edge to edge at one uniform scale, as a seamless tileable texture. "
        "The first reference image is the place this material belongs to: take its colours, its age and its character from there, and nothing of its composition. " + REAL
        + "Output one square image. Photographic, sharp from edge to edge, no depth of field blur, no vignette, no horizon, no sky, no text, no logo, no people, no animals.")
ONBLACK = ("The subject lies on pure black: black means nothing is there, and brightness means how much is there. The field fills the whole frame edge to edge at one uniform scale, as a seamless tileable texture. "
           "The first reference image is the place this belongs to: take its colour and its character from there, and nothing of its composition. " + REAL
           + "Output one square image. Photographic, sharp, no horizon, no sky, no text, no logo, no people, no animals.")
BLIND = " The animal has no eyes and no ears anywhere on it and no face: it is not a monster and not cute, an animal of an unknown world built for one way of feeding."
DOWN = "A material texture, seen straight down from above in an orthographic view: "

H_GROUND = ("The reference image is a photograph of ground seen straight down from above. Make its height map: the same picture, pixel for pixel, as a greyscale height field for relief shading. "
            "White is the highest ground and black is the lowest. Cracks, hollows, channels and standing water are dark; the tops and raised edges of blocks, slabs, stones and lumps are light. "
            "Smooth continuous greys that keep every edge and every small form exactly where it is in the reference image. No shading, no shadows, no light direction, no colour, no outlines, no contour lines, no text.")
H_FACE = ("The reference image is a photograph of a rock face seen square on. Make its relief map: the same picture, pixel for pixel, as a greyscale depth field for relief shading. "
          "White is what stands furthest out toward the viewer and black is what lies deepest in. Cracks, joints, caves, hollows and undercut bands are dark; ledges, ribs, bulges and the noses of blocks are light. "
          "Smooth continuous greys that keep every edge and every small form exactly where it is in the reference image. No shading, no shadows, no light direction, no colour, no outlines, no contour lines, no text.")
H_SHEET = ("The reference image shows one subject on a black background. Make its relief map: the same picture, pixel for pixel, as a greyscale depth field for relief shading. The background stays pure black. "
           "On the subject, white is what stands nearest to the viewer and dark grey is what lies furthest back. Cracks, holes, hollows and folds are dark; ridges, bulges, bones and raised edges are light. "
           "Smooth continuous greys that keep every outline and every small form exactly where it is in the reference image. No shading, no shadows, no light direction, no colour, no outlines, no contour lines, no text.")

rows = []
def add(place, name, kind, prompt, key, real, why, metres, aspect='16:9', height=None, asked='the Builder, unasked', group=1, refs=None):
    assert not any(r['place'] == place and r['name'] == name for r in rows), (place, name)
    rows.append(dict(place=place, name=name, kind=kind, prompt=prompt, refs=refs or [ap(place, key) if isinstance(key, int) else A + key, R + real], why=why, metres=metres,
                     aspect=aspect, height=height, asked=asked, group=group, model='gpt_image_2_6_flare', date='2026-11-26'))
def back(place, name, head, key, real, why, **k):
    add(place, name, 'plate', head + ' ' + BACK, key, real, why, 0, '16:9', None, **k)
def sheet(place, name, head, key, real, why, metres, aspect='16:9', height=False, animal=False, **k):
    add(place, name, 'plate', head + (BLIND if animal else '') + ' ' + SHEET, key, real, why, metres, aspect, H_SHEET if height else None, **k)
def face(place, name, head, key, real, why, metres, aspect='16:9', height=True, **k):
    add(place, name, 'plate', head + ' ' + FILL, key, real, why, metres, aspect, H_FACE if height else None, **k)
def ground(place, name, head, key, real, why, metres, aspect='16:9', height=True, **k):
    add(place, name, 'plate', head + ' ' + GROUND, key, real, why, metres, aspect, H_GROUND if height else None, **k)
def tile(place, name, head, key, real, why, metres, **k):
    add(place, name, 'tile', head + ' ' + TILE, key, real, why, metres, '1:1', None, **k)
def onblack(place, name, head, key, real, why, metres, tiled=True, **k):
    add(place, name, 'tile' if tiled else 'plate', head + ' ' + (ONBLACK if tiled else ONBLACK.replace('The field fills the whole frame edge to edge at one uniform scale, as a seamless tileable texture. ', '')), key, real, why, metres, '1:1', None, **k)

